import React, { useRef, useCallback, useMemo, useState, useEffect } from "react";
import ForceGraph2D from "react-force-graph-2d";
import { useNavigate } from "react-router-dom";
import projectsData from "../data/projectsData";
import "../styles/ResearchNetwork.css";

const TOPIC_COLORS = {
  LLM: "#666",
  Personalization: "#888",
  "AI Safety": "#555",
  HCI: "#777",
  Fashion: "#999",
};

const ResearchNetwork = () => {
  const fgRef = useRef();
  const containerRef = useRef();
  const navigate = useNavigate();
  const [hoveredNode, setHoveredNode] = useState(null);
  const [dimensions, setDimensions] = useState({ width: 800, height: 500 });

  useEffect(() => {
    const updateSize = () => {
      if (containerRef.current) {
        setDimensions({
          width: containerRef.current.offsetWidth,
          height: 500,
        });
      }
    };
    updateSize();
    window.addEventListener("resize", updateSize);
    return () => window.removeEventListener("resize", updateSize);
  }, []);

  const graphData = useMemo(() => {
    const nodes = [];
    const links = [];
    const topicNodes = new Set();

    // Add topic nodes
    const topicKeywords = {
      LLM: ["LLM"],
      Personalization: ["Personalization", "Psychology"],
      "AI Safety": ["AI Safety", "Bias", "Attack", "Persuasion"],
      HCI: ["HCI", "Personality Detection", "OCEAN", "Multi-Agent"],
      Fashion: ["Fashion", "Retrieval"],
    };

    Object.keys(topicKeywords).forEach((topic) => {
      nodes.push({
        id: `topic-${topic}`,
        name: topic,
        type: "topic",
        color: TOPIC_COLORS[topic],
        val: 20,
      });
      topicNodes.add(`topic-${topic}`);
    });

    // Add project nodes and links to topics
    projectsData.forEach((project) => {
      const nodeId = `project-${project.id}`;
      nodes.push({
        id: nodeId,
        name: project.title,
        type: "project",
        status: project.status,
        color: project.status === "ongoing" ? "#333" : "#aaa",
        val: 12,
        projectData: project,
      });

      // Link to matching topics
      Object.entries(topicKeywords).forEach(([topic, keywords]) => {
        if (project.keywords.some((kw) => keywords.includes(kw))) {
          links.push({
            source: `topic-${topic}`,
            target: nodeId,
            color: "#ddd",
          });
        }
      });
    });

    // Add inter-project links for shared keywords
    for (let i = 0; i < projectsData.length; i++) {
      for (let j = i + 1; j < projectsData.length; j++) {
        const shared = projectsData[i].keywords.filter((kw) =>
          projectsData[j].keywords.includes(kw)
        );
        if (shared.length > 0) {
          links.push({
            source: `project-${projectsData[i].id}`,
            target: `project-${projectsData[j].id}`,
            color: "#eee",
            dashed: true,
          });
        }
      }
    }

    return { nodes, links };
  }, []);

  const paintNode = useCallback(
    (node, ctx, globalScale) => {
      const isHovered = hoveredNode === node.id;
      const radius = node.type === "topic" ? 24 : 16;
      const fontSize = node.type === "topic" ? 13 / globalScale : 10 / globalScale;

      // Node circle
      ctx.beginPath();
      ctx.arc(node.x, node.y, radius / globalScale, 0, 2 * Math.PI);
      ctx.fillStyle = isHovered ? "#333" : node.color;
      ctx.fill();

      if (node.status === "ongoing") {
        ctx.strokeStyle = "#333";
        ctx.lineWidth = 2 / globalScale;
        ctx.stroke();
      }

      // Label
      ctx.font = `${node.type === "topic" ? "bold " : ""}${fontSize}px Google Sans, sans-serif`;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillStyle = "#fff";

      if (node.type === "topic") {
        ctx.fillText(node.name, node.x, node.y);
      } else {
        // Truncate project name
        const maxLen = 18;
        const label =
          node.name.length > maxLen
            ? node.name.substring(0, maxLen) + "…"
            : node.name;
        ctx.fillText(label, node.x, node.y);
      }

      // Tooltip on hover
      if (isHovered && node.type === "project") {
        const tooltipFontSize = 11 / globalScale;
        ctx.font = `${tooltipFontSize}px Google Sans, sans-serif`;
        const text = node.name;
        const textWidth = ctx.measureText(text).width;
        const padding = 6 / globalScale;
        const tooltipY = node.y - radius / globalScale - 20 / globalScale;

        ctx.fillStyle = "rgba(0,0,0,0.85)";
        ctx.beginPath();
        ctx.roundRect(
          node.x - textWidth / 2 - padding,
          tooltipY - tooltipFontSize / 2 - padding,
          textWidth + padding * 2,
          tooltipFontSize + padding * 2,
          4 / globalScale
        );
        ctx.fill();

        ctx.fillStyle = "#fff";
        ctx.fillText(text, node.x, tooltipY);
      }
    },
    [hoveredNode]
  );

  const handleNodeClick = useCallback(
    (node) => {
      if (node.type === "project") {
        navigate("/projects");
      }
    },
    [navigate]
  );

  return (
    <section className="research-network">
      <h2>Research Map</h2>
      <p className="network-subtitle">
        Click a project node to explore details. Topics are connected to related projects.
      </p>
      <div className="network-container" ref={containerRef}>
        <ForceGraph2D
          ref={fgRef}
          graphData={graphData}
          width={dimensions.width}
          height={dimensions.height}
          nodeCanvasObject={paintNode}
          nodePointerAreaPaint={(node, color, ctx, globalScale) => {
            const radius = node.type === "topic" ? 24 : 16;
            ctx.beginPath();
            ctx.arc(node.x, node.y, radius / globalScale, 0, 2 * Math.PI);
            ctx.fillStyle = color;
            ctx.fill();
          }}
          linkColor={(link) => link.color}
          linkWidth={1}
          linkLineDash={(link) => (link.dashed ? [4, 4] : null)}
          onNodeHover={(node) => setHoveredNode(node ? node.id : null)}
          onNodeClick={handleNodeClick}
          cooldownTicks={100}
          d3AlphaDecay={0.05}
          d3VelocityDecay={0.3}
          enableZoomInteraction={false}
          enablePanInteraction={false}
          backgroundColor="transparent"
        />
      </div>
    </section>
  );
};

export default ResearchNetwork;
